const defaults={text:"#ffffff",line:"#ffffff",accent:"#ffb000",lineWidth:2};
class InstrumentStyleEditor extends HTMLElement{connectedCallback(){const profile=this.getAttribute("profile")||"rov",target=this.getAttribute("target")||"instrument",key=`rov.instrument-style.${profile}.${target}`;let s={...defaults};try{s={...s,...JSON.parse(localStorage.getItem(key)||"{}")} }catch{}this.innerHTML=`<button class="instrument-style-editor__toggle" type="button" aria-expanded="false"><i class="fa-solid fa-sliders"></i> HUD style</button><form class="instrument-style-editor__popover" hidden><h2>HUD appearance</h2><label>Text colour<input name="text" type="color" value="${s.text}"></label><label>Line colour<input name="line" type="color" value="${s.line}"></label><label>Accent colour<input name="accent" type="color" value="${s.accent}"></label><label>Line thickness<output data-width>${s.lineWidth}px</output><input name="lineWidth" type="range" min="1" max="6" value="${s.lineWidth}"></label><button type="submit">Save</button></form>`;const p=this.querySelector("form"),t=this.querySelector("button"),read=()=>({text:this.querySelector("[name=text]").value,line:this.querySelector("[name=line]").value,accent:this.querySelector("[name=accent]").value,lineWidth:Number(this.querySelector("[name=lineWidth]").value)}),emit=x=>{localStorage.setItem(key,JSON.stringify(x));document.dispatchEvent(new CustomEvent("rov-instrument-style",{detail:{target,style:x}}))};t.onclick=()=>{p.hidden=!p.hidden;t.setAttribute("aria-expanded",String(!p.hidden))};this.querySelector("[name=lineWidth]").oninput=e=>this.querySelector("[data-width]").textContent=`${e.target.value}px`;p.onsubmit=e=>{e.preventDefault();emit(read())};emit(s)}}customElements.define("rov-instrument-style-editor",InstrumentStyleEditor);
